function removePalindromeSub(s) {
  // Short strings: breadth-first search over which letters remain, trying every palindromic subset as one move.
  // Long strings (beyond an exhaustive search): compare s with its reverse.
  const n = s.length;
  if (n > 12) return s === s.split('').reverse().join('') ? 1 : 2;
  const isPalindrome = (mask) => {
    const chars = [];
    for (let i = 0; i < n; i++) if (mask & (1 << i)) chars.push(s[i]);
    return chars.join('') === chars.slice().reverse().join('');
  };
  const full = (1 << n) - 1;
  const distance = new Map([[full, 0]]);
  const queue = [full];
  while (queue.length) {
    const mask = queue.shift();
    if (mask === 0) return distance.get(mask);
    for (let sub = mask; sub > 0; sub = (sub - 1) & mask) {
      const next = mask & ~sub;
      if (!distance.has(next) && isPalindrome(sub)) {
        distance.set(next, distance.get(mask) + 1);
        queue.push(next);
      }
    }
  }
  return -1;
}

