function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const letter = () => (rand() < 0.5 ? 'a' : 'b');
  const n = size === 'large' ? 900 + pick(101) : 1 + pick(8);
  const shape = pick(3);
  const chars = [];
  for (let i = 0; i < n; i++) chars.push(letter());
  if (shape > 0) {
    // Mirror the first half to make a palindrome.
    for (let i = 0; i < Math.floor(n / 2); i++) chars[n - 1 - i] = chars[i];
    // Sometimes break it with a single mismatched pair.
    if (shape === 2 && n > 1) {
      const i = pick(Math.floor(n / 2));
      chars[n - 1 - i] = chars[i] === 'a' ? 'b' : 'a';
    }
  }
  return [chars.join('')];
}
